window.ЗВУК = (function () {
const НАСТРОЙКИ = window.МИР_НАСТРОЙКИ;
let уши = null;
let тихо = false;
try { тихо = localStorage.getItem(НАСТРОЙКИ.звук.ключ) === НАСТРОЙКИ.звук.тихо; } catch (е) { тихо = false; }
function завести() {
  if (!уши) {
    const Уши = window.AudioContext || window.webkitAudioContext;
    if (!Уши) return null;
    уши = new Уши();
  }
  if (уши.state === НАСТРОЙКИ.звук.спит) уши.resume().catch(() => {});
  return уши;
}
function тон(т) {
  if (тихо) return;
  const у = завести();
  if (!у) return;
  const начало = у.currentTime + (т.через || 0);
  const волна = у.createOscillator(), сила = у.createGain();
  волна.type = т.форма;
  волна.frequency.setValueAtTime(т.от, начало);
  if (т.до) волна.frequency.exponentialRampToValueAtTime(т.до, начало + т.длина);
  сила.gain.setValueAtTime(т.громкость, начало);
  сила.gain.exponentialRampToValueAtTime(НАСТРОЙКИ.звук.тише, начало + т.длина);
  волна.connect(сила);
  сила.connect(у.destination);
  волна.start(начало);
  волна.stop(начало + т.длина);
}
function шаг() {
  const з = НАСТРОЙКИ.звук.шаг;
  тон({ форма: з.форма, от: з.от + Math.random() * з.разброс, до: з.до, громкость: з.громкость, длина: з.длина });
}
function щелчок() {
  const з = НАСТРОЙКИ.звук.щелчок;
  тон({ форма: з.форма, от: з.от, до: з.до, громкость: з.громкость, длина: з.длина });
}
function дверь() {
  const з = НАСТРОЙКИ.звук.дверь;
  з.ноты.forEach((нота, и) => тон({ форма: з.форма, от: нота, громкость: з.громкость, длина: з.длина, через: и * з.шаг }));
}
function ворота() {
  const з = НАСТРОЙКИ.звук.ворота;
  тон({ форма: з.форма, от: з.от, до: з.до, громкость: з.громкость, длина: з.длина });
}
let прежде = null;
function пройдено(путь) {
  if (прежде === null || путь < прежде) { прежде = путь; return; }
  if (путь - прежде >= НАСТРОЙКИ.звук.шаг.через) { прежде = путь; шаг(); }
}
function переключить() {
  тихо = !тихо;
  try { localStorage.setItem(НАСТРОЙКИ.звук.ключ, тихо ? НАСТРОЙКИ.звук.тихо : НАСТРОЙКИ.звук.громко); } catch (е) {  }
  if (!тихо) щелчок();
  return тихо;
}
return { шаг: шаг, щелчок: щелчок, дверь: дверь, ворота: ворота, пройдено: пройдено,
         переключить: переключить, тихо: () => тихо, завести: завести };
})();
